import { Router } from 'express';
import { CreateProjectUseCase } from '../../../application/use-cases/CreateProjectUseCase';
import { Dependencies } from '../../composition/Dependencies';
import { ProjectController } from '../controllers/ProjectController';

export function projectRoutes(deps: Dependencies): Router {
  const controller = new ProjectController(new CreateProjectUseCase(deps.projects, deps.ids));

  const router = Router();
  router.post('/projects', controller.create);
  return router;
}

